// Cast returns the typed view of n, or nil for a nil node.
func Cast(n *syntax.Node) Node {
	if n == nil {
		return nil
	}
	switch n.Kind {
	case syntax.Action:
		return Action{n}
	case syntax.Annotation:
		return Annotation{n}
	case syntax.Args:
		return Args{n}
	case syntax.ArrayExpr:
		return ArrayExpr{n}
	case syntax.AssignStmt:
		return AssignStmt{n}
	case syntax.BinaryExpr:
		return BinaryExpr{n}
	case syntax.CallExpr:
		return CallExpr{n}
	case syntax.CastExpr:
		return CastExpr{n}
	case syntax.Code:
		return Code{n}
	case syntax.CommentLine:
		return CommentLine{n}
	case syntax.Declare:
		return Declare{n}
	case syntax.DoBlock:
		return DoBlock{n}
	case syntax.Doc:
		return Doc{n}
	case syntax.DocLine:
		return DocLine{n}
	case syntax.Enter:
		return Enter{n}
	case syntax.ErrorNode:
		return ErrorNode{n}
	case syntax.ExprStmt:
		return ExprStmt{n}
	case syntax.Fence:
		return Fence{n}
	case syntax.FieldExpr:
		return FieldExpr{n}
	case syntax.File:
		return File{n}
	case syntax.Flags:
		return Flags{n}
	case syntax.ForExpr:
		return ForExpr{n}
	case syntax.Heading:
		return Heading{n}
	case syntax.HeronFence:
		return HeronFence{n}
	case syntax.IfExpr:
		return IfExpr{n}
	case syntax.Insert:
		return Insert{n}
	case syntax.IntersectionType:
		return IntersectionType{n}
	case syntax.Invoke:
		return Invoke{n}
	case syntax.Let:
		return Let{n}
	case syntax.LetStmt:
		return LetStmt{n}
	case syntax.Link:
		return Link{n}
	case syntax.Literal:
		return Literal{n}
	case syntax.MapEntry:
		return MapEntry{n}
	case syntax.MapExpr:
		return MapExpr{n}
	case syntax.NamedArg:
		return NamedArg{n}
	case syntax.NamedType:
		return NamedType{n}
	case syntax.OptionalType:
		return OptionalType{n}
	case syntax.Param:
		return Param{n}
	case syntax.Params:
		return Params{n}
	case syntax.ParenExpr:
		return ParenExpr{n}
	case syntax.Path:
		return Path{n}
	case syntax.PathExpr:
		return PathExpr{n}
	case syntax.PositionalArg:
		return PositionalArg{n}
	case syntax.ProseBlock:
		return ProseBlock{n}
	case syntax.ProseFile:
		return ProseFile{n}
	case syntax.ProseLine:
		return ProseLine{n}
	case syntax.ProseLines:
		return ProseLines{n}
	case syntax.ReturnStmt:
		return ReturnStmt{n}
	case syntax.Scope:
		return Scope{n}
	case syntax.Set:
		return Set{n}
	case syntax.StringLit:
		return StringLit{n}
	case syntax.StringPart:
		return StringPart{n}
	case syntax.StructBody:
		return StructBody{n}
	case syntax.Tag:
		return Tag{n}
	case syntax.TagAttr:
		return TagAttr{n}
	case syntax.TagClose:
		return TagClose{n}
	case syntax.TextNode:
		return TextNode{n}
	case syntax.UnaryExpr:
		return UnaryExpr{n}
	case syntax.UnionType:
		return UnionType{n}
	case syntax.Value:
		return Value{n}
	}
	return nil
}
